return ['domain'=>'ludoya','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ca','project-id-version'=>'Ludoya 0.2.0','pot-creation-date'=>'2026-09-04T01:14:46+00:00','po-revision-date'=>'2026-09-04T01:14:46+00:00','messages'=>['Ludoya'=>'Ludoya','https://ludoya.com'=>'https://ludoya.com','Show your Ludoya events, collection and stats on your WordPress site, and run your event admin from wp-admin.'=>'Mostra els teus esdeveniments, la teva col·lecció i les teves estadístiques de Ludoya al teu web de WordPress, i gestiona els teus esdeveniments des de wp-admin.','Events'=>'Esdeveniments','Add event'=>'Afegeix un esdeveniment','Form templates'=>'Plantilles de formulari','Settings'=>'Configuració','Searching…'=>'S\'està cercant…','Copied'=>'Copiat','Copy this:'=>'Copia això:','Nothing found.'=>'No s\'ha trobat res.','Delete this event permanently? Cancelling instead keeps it visible to attendees.'=>'Vols eliminar aquest esdeveniment definitivament? Si el canceles, continuarà sent visible per als assistents.','You are not allowed to do this.'=>'No tens permís per fer això.','Settings saved.'=>'Configuració desada.','No Ludoya API key configured. Add one under Ludoya, Settings.'=>'No hi ha cap clau d\'API de Ludoya configurada. Afegeix-ne una a Ludoya, Configuració.','Ludoya rejected the API key. Check it under Ludoya, Settings.'=>'Ludoya ha rebutjat la clau d\'API. Revisa-la a Ludoya, Configuració.','The Ludoya public API requires the Business plan.'=>'L\'API pública de Ludoya requereix el pla Business.','This event changed in Ludoya while you were editing it here. Reload the page and try again.'=>'Aquest esdeveniment ha canviat a Ludoya mentre l\'editaves aquí. Torna a carregar la pàgina i prova-ho de nou.','Ludoya rate limit reached. Try again in %s seconds.'=>'S\'ha assolit el límit de peticions de Ludoya. Torna-ho a provar d\'aquí a %s segons.','Ludoya returned HTTP %d.'=>'Ludoya ha retornat HTTP %d.','An event needs a title.'=>'Un esdeveniment necessita un títol.','Event created.'=>'Esdeveniment creat.','Event updated.'=>'Esdeveniment actualitzat.','Event published.'=>'Esdeveniment publicat.','Event cancelled. Attendees have been notified.'=>'Esdeveniment cancel·lat. S\'ha avisat els assistents.','Event deleted.'=>'Esdeveniment eliminat.','Unknown action.'=>'Acció desconeguda.','Participant removed.'=>'Participant eliminat.','Pick a Ludoya user, or give a name and a valid email address.'=>'Tria un usuari de Ludoya, o indica un nom i un email vàlid.','Participant added.'=>'Participant afegit.','Form template deleted.'=>'Plantilla de formulari eliminada.','Title'=>'Títol','Type'=>'Tipus','When'=>'Quan','Signed up'=>'Inscrits','Status'=>'Estat','No events found.'=>'No s\'ha trobat cap esdeveniment.','Edit'=>'Editar','View on Ludoya'=>'Mostra a Ludoya','Copy shortcode'=>'Copia el shortcode','Publish'=>'Publica','Cancel'=>'Cancel·la','Delete'=>'Elimina','Cancelled'=>'Cancel·lat','Draft'=>'Esborrany','Past'=>'Passat','Upcoming'=>'Proper','No events scheduled right now.'=>'Ara mateix no hi ha cap esdeveniment programat.','Sign-ups are closed.'=>'Les inscripcions estan tancades.','Missing event.'=>'Falta l\'esdeveniment.','Thanks! Your sign-up has been sent.'=>'Gràcies! S\'ha enviat la teva inscripció.','Too many attempts. Please wait a minute and try again.'=>'Massa intents. Espera un minut i torna-ho a provar.','Please accept the terms to sign up.'=>'Accepta les condicions per inscriure\'t.','A name and a valid email address are required.'=>'Calen un nom i un email vàlid.','You are signed up. Check your inbox to claim your Ludoya account.'=>'Ja estàs inscrit. Revisa el teu correu per reclamar el teu compte de Ludoya.','Date not decided'=>'Data per decidir','Today'=>'Avui','Tomorrow'=>'Demà','Meetup'=>'Quedada','Planned play'=>'Partida planificada','Tournament'=>'Torneig','Play booth'=>'Punt de joc','Public'=>'Públic','Group only'=>'Només el grup','Friends only'=>'Només amics','Private'=>'Privat','A list of your events'=>'Una llista dels teus esdeveniments','Ludoya events'=>'Esdeveniments de Ludoya','One event, with its sign-up form'=>'Un esdeveniment, amb el seu formulari d\'inscripció','Ludoya event'=>'Esdeveniment de Ludoya','Put this on its own page and point your events list at it, as below. It shows whichever event the visitor clicked.'=>'Posa\'l en una pàgina pròpia i apunta-hi la teva llista d\'esdeveniments, tal com s\'explica a sota. Mostra l\'esdeveniment on hagi clicat la visita.','A sign-up form on its own'=>'Només el formulari d\'inscripció','Ludoya sign-up form'=>'Formulari d\'inscripció de Ludoya','Same page rule, and only appears once you switch sign-ups on above.'=>'Mateixa norma de pàgina, i només apareix quan actives les inscripcions més amunt.','The games you own'=>'Els jocs que tens','Ludoya collection'=>'Col·lecció de Ludoya','How much you have played, and what'=>'Quant has jugat, i a què','Ludoya stats'=>'Estadístiques de Ludoya','Where you play'=>'On jugueu','Ludoya locations'=>'Ubicacions de Ludoya','Edit event'=>'Edita l\'esdeveniment','Publish draft'=>'Publica l\'esborrany','This Ludoya API is older than the plugin: it does not report visibility, attendance approval or the participation limits. Those four are shown at their defaults below and are left exactly as they are when you save.'=>'Aquesta API de Ludoya és més antiga que el plugin: no informa de la visibilitat, l\'aprovació d\'assistència ni els límits de participació. Aquests quatre camps es mostren a sota amb els valors per defecte i es deixen tal com estan en desar.','Description'=>'Descripció','Starts'=>'Comença','Times are in %s.'=>'Les hores són en %s.','Ends'=>'Acaba','Location'=>'Ubicació','The organisation default'=>'La predeterminada de l\'organització','Any table'=>'Qualsevol taula','Table choices follow the location.'=>'Les taules depenen de la ubicació.','Game'=>'Joc','Search the catalogue…'=>'Cerca al catàleg…','Capacity'=>'Capacitat','Leave empty for no limit.'=>'Deixa-ho buit per no posar-hi límit.','Minimum participants'=>'Participants mínims','Leave empty for no minimum.'=>'Deixa-ho buit per no posar-hi mínim.','Seats one person may reserve'=>'Places que pot reservar una persona','Visibility'=>'Visibilitat','Attendance'=>'Assistència','Organisers approve each sign-up'=>'Els organitzadors aproven cada inscripció','Unticked, anybody may sign up.'=>'Sense marcar, qualsevol s\'hi pot inscriure.','Teaching'=>'Ensenya','Search members…'=>'Cerca membres…','Game master'=>'Màster','Image URL'=>'URL de la imatge','Ludoya downloads and stores the image. Leave empty to keep the current one.'=>'Ludoya descarrega i desa la imatge. Deixa-ho buit per mantenir l\'actual.','Sign-up form'=>'Formulari d\'inscripció','Leave as it is'=>'Deixa-ho com està','No form of its own'=>'Sense formulari propi','This event has its own questions, set in the Ludoya app. Choosing a template here replaces them.'=>'Aquest esdeveniment té preguntes pròpies, definides a l\'app de Ludoya. Si tries una plantilla aquí, les substituiràs.','This event currently inherits its parent event\'s questions.'=>'Ara mateix aquest esdeveniment hereta les preguntes de l\'esdeveniment pare.','Templates are authored in the Ludoya app; pick one here.'=>'Les plantilles es creen a l\'app de Ludoya; aquí només en tries una.','Your own id'=>'El teu propi id','Optional. If this event also exists in another system, put its id here so the two stay matched.'=>'Opcional. Si aquest esdeveniment també existeix en un altre sistema, posa-hi el seu id perquè tots dos quedin aparellats.','Create it hidden, for review before anybody sees it'=>'Crea\'l ocult, per revisar-lo abans que ningú el vegi','Publishing later changes the event link, so do not share it before then.'=>'Publicar-lo després canvia l\'enllaç de l\'esdeveniment, així que no el comparteixis abans.','Create event'=>'Crea l\'esdeveniment','Save changes'=>'Desa els canvis','Give this event its own page'=>'Dona a aquest esdeveniment la seva pàgina','For a big one-off you want in your menu, make a page for it and paste this in. Your general events page does not need any of this — it links every event to one shared page instead.'=>'Per a un esdeveniment únic i gran que vulguis al teu menú, crea-li una pàgina i enganxa-hi això. La teva pàgina general d\'esdeveniments no necessita res d\'això: enllaça tots els esdeveniments a una mateixa pàgina compartida.','Copy'=>'Copia','Participants'=>'Participants','%d signed up so far. The public API does not list them by name; open the event in Ludoya to see the roster.'=>'%d inscrits fins ara. L\'API pública no els llista pel nom; obre l\'esdeveniment a Ludoya per veure\'n la llista.','Existing Ludoya user'=>'Usuari de Ludoya existent','Search users…'=>'Cerca usuaris…','Or sign somebody up by name and email — Ludoya creates the account for them to claim later.'=>'O inscriu algú amb el seu nom i el seu email: Ludoya li crea el compte perquè el reclami més endavant.','Name'=>'Nom','Email'=>'Email','Add participant'=>'Afegeix un participant','Remove somebody'=>'Treu algú','Remove participant'=>'Treu el participant','All'=>'Tots','No API key yet.'=>'Encara no hi ha cap clau d\'API.','Add one in settings.'=>'Afegeix-ne una a la configuració.','A template is a set of sign-up questions shared by several events. Editing one changes every event that uses it.'=>'Una plantilla és un conjunt de preguntes d\'inscripció compartit per diversos esdeveniments. Si l\'edites, canvien tots els esdeveniments que la fan servir.','No templates yet. Create one in the Ludoya app, then attach it to an event here.'=>'Encara no hi ha plantilles. Crea\'n una a l\'app de Ludoya i aquí la podràs assignar a un esdeveniment.','Questions'=>'Preguntes','Updated'=>'Actualitzada','Deleting detaches the template from any event still using it; those events end up asking nothing.'=>'En eliminar-la es desvincula dels esdeveniments que la facin servir; aquests esdeveniments deixen de preguntar res.','Ludoya settings'=>'Configuració de Ludoya','Connected. Your organisation has %d locations.'=>'Connectat. La teva organització té %d ubicacions.','API key'=>'Clau d\'API','is defined in wp-config.php, so the key is read from there.'=>'està definida a wp-config.php, així que la clau es llegeix d\'allà.','Create one in Ludoya under your organisation profile, Developer. Requires the Business plan. Leave blank to keep the current key.'=>'Crea-la a Ludoya, al perfil de la teva organització, apartat Desenvolupador. Requereix el pla Business. Deixa-ho en blanc per mantenir la clau actual.','For a stricter setup, define LUDOYA_API_KEY in wp-config.php instead and this field disappears.'=>'Per a una configuració més estricta, defineix LUDOYA_API_KEY a wp-config.php i aquest camp desapareixerà.','Cache'=>'Memòria cau','seconds'=>'segons','How long a page keeps its copy of the data. Without this, every visitor costs an API call. Editing an event here clears the cache immediately.'=>'Quanta estona guarda una pàgina la seva còpia de les dades. Sense això, cada visita costa una crida a l\'API. Editar un esdeveniment aquí buida la memòria cau a l\'instant.','Timeout'=>'Temps d\'espera','Sign-ups'=>'Inscripcions','Let visitors sign up for events from this site'=>'Permet que les visites s\'inscriguin als esdeveniments des d\'aquest web','A sign-up creates a Ludoya account for the address given, so keep this off unless your privacy notice covers it.'=>'Una inscripció crea un compte de Ludoya per a l\'adreça indicada, així que deixa-ho desactivat si el teu avís de privacitat no ho contempla.','Consent text'=>'Text de consentiment','Shown beside the checkbox on the sign-up form. Leave empty for the default wording.'=>'Es mostra al costat de la casella del formulari d\'inscripció. Deixa-ho buit per fer servir el text per defecte.','Connection'=>'Connexió','Test connection'=>'Prova la connexió','Rate limit at the last call: %1$d of %2$d requests left this minute.'=>'Límit de peticions a l\'última crida: queden %1$d de %2$d peticions aquest minut.','Putting Ludoya on your pages'=>'Posar Ludoya a les teves pàgines','Edit any page, press the + button, search for "Ludoya" and pick what you want to show. Nothing needs setting up to start with; each one has its own options in the sidebar on the right — how many events, which layout, and so on — once you want to change something.'=>'Edita qualsevol pàgina, prem el botó +, cerca "Ludoya" i tria què vols mostrar. Per començar no cal configurar res; cada bloc té les seves opcions a la barra lateral de la dreta (quants esdeveniments, quin disseny, etc.) quan vulguis canviar alguna cosa.','To show this'=>'Per mostrar això','Add this block'=>'Afegeix aquest bloc','Or paste this, in an older editor'=>'O enganxa això, en un editor antic','Showing an event on your own site'=>'Mostrar un esdeveniment al teu propi web','By default an event card sends the visitor off to the Ludoya app. There are two ways to keep them here, and most clubs end up using both.'=>'Per defecte, la targeta d\'un esdeveniment envia la visita a l\'app de Ludoya. Hi ha dues maneres que es quedi aquí, i la majoria de clubs acaben fent servir totes dues.','One page that serves every event'=>'Una pàgina que serveix per a tots els esdeveniments','For your regular programme, where the events change every month and you do not want a new page each time.'=>'Per a la teva programació habitual, on els esdeveniments canvien cada mes i no vols crear una pàgina nova cada vegada.','Make a page called Event, put the "Ludoya event" block on it, and leave its settings empty.'=>'Crea una pàgina anomenada Esdeveniment, posa-hi el bloc "Esdeveniment de Ludoya" i deixa les seves opcions buides.','On the page listing your events, select the "Ludoya events" block and set %s to that page.'=>'A la pàgina que llista els teus esdeveniments, selecciona el bloc "Esdeveniments de Ludoya" i apunta %s a aquesta pàgina.','Event page'=>'Pàgina de l\'esdeveniment','Every card now links to your Event page, which works out which event to show from the link it was opened with.'=>'Ara cada targeta enllaça a la teva pàgina Esdeveniment, que dedueix quin esdeveniment ha de mostrar a partir de l\'enllaç amb què s\'ha obert.','A page dedicated to one event'=>'Una pàgina dedicada a un sol esdeveniment','For a tournament or an open day you want in your menu, with its own address and its own words around it.'=>'Per a un torneig o una jornada de portes obertes que vulguis al teu menú, amb la seva pròpia adreça i les teves paraules al voltant.','Open %1$s, find the event, and press %2$s underneath its name.'=>'Obre %1$s, busca l\'esdeveniment i prem %2$s sota el seu nom.','Ludoya, Events'=>'Ludoya, Esdeveniments','Paste it into any page. Write whatever you like around it.'=>'Enganxa\'l a qualsevol pàgina. Escriu-hi el que vulguis al voltant.','That page shows only that event, whatever anybody clicks elsewhere. The same shortcode sits on the edit screen for each event.'=>'Aquesta pàgina mostra només aquest esdeveniment, faci clic on faci clic la visita. El mateix shortcode és a la pantalla d\'edició de cada esdeveniment.','Changing how any of it looks'=>'Canviar com es veu tot això','These views follow your theme. To go further, copy a file out of %1$s into %2$s in your theme and edit it there; the plugin will use yours instead.'=>'Aquestes vistes segueixen el teu tema. Per anar més enllà, copia un fitxer de %1$s a %2$s dins del teu tema i edita\'l allà; el plugin farà servir el teu.','%1$d games and %2$d expansions'=>'%1$d jocs i %2$d expansions','Nothing in the collection yet.'=>'Encara no hi ha res a la col·lecció.','%d players'=>'%d jugadors','%1$d–%2$d players'=>'%1$d–%2$d jugadors','%d going'=>'%d apuntat' . "\0" . '%d apuntats','Full'=>'Plena','%d seat left'=>'Queda %d plaça' . "\0" . 'Queden %d places','All events'=>'Tots els esdeveniments','%1$d of %2$d seats left'=>'Queden %1$d de %2$d places','Sign up on Ludoya'=>'Inscriu-te a Ludoya','Past events'=>'Esdeveniments passats','No locations yet.'=>'Encara no hi ha ubicacions.','Room for %d'=>'Espai per a %d','Gender'=>'Gènere','Date of birth'=>'Data de naixement','Phone number'=>'Telèfon','This event is full.'=>'Aquest esdeveniment és ple.','Sign up'=>'Inscriu-te','Choose…'=>'Tria…','I agree that my name and email are sent to Ludoya to register my place, and that a Ludoya account is created for me.'=>'Accepto que el meu nom i el meu email s\'enviïn a Ludoya per registrar la meva plaça, i que se\'m creï un compte de Ludoya.','Leave this field empty'=>'Deixa aquest camp buit','Sign me up'=>'Inscriu-me','Plays'=>'Partides','Different games'=>'Jocs diferents','Players'=>'Jugadors','Time played'=>'Temps jugat','Most played'=>'Més jugats','%d play'=>'%d partida' . "\0" . '%d partides','Heading'=>'Encapçalament','How many'=>'Quants','Past events to include'=>'Esdeveniments passats a incloure','Only this type'=>'Només aquest tipus','Every type'=>'Tots els tipus','Sub-events'=>'Subesdeveniments','Only top-level events'=>'Només esdeveniments principals','Include sub-events'=>'Inclou els subesdeveniments','Layout'=>'Disseny','Cards'=>'Targetes','List'=>'Llista','Event page (id, slug or URL)'=>'Pàgina de l\'esdeveniment (id, slug o URL)','Event id (empty reads it from the link)'=>'Id de l\'esdeveniment (buit, el llegeix de l\'enllaç)','Show it'=>'Mostra\'l','Hide it'=>'Amaga\'l','How many games'=>'Quants jocs','Filter by name'=>'Filtra per nom','Grid'=>'Graella','Period'=>'Període','All time'=>'Des de sempre','Last year'=>'Últim any','Last month'=>'Últim mes','Last 30 days'=>'Últims 30 dies','Last 7 days'=>'Últims 7 dies','Games to list'=>'Jocs a llistar']];